const db = getFirestore();

const tonsMaiores = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const tonsMenores = ['Cm', 'C#m', 'Dm', 'D#m', 'Em', 'Fm', 'F#m', 'Gm', 'G#m', 'Am', 'A#m', 'Bm'];

export interface Musica {
  nome: string;
  tom: string;
  linkLetra?: string;
  linkYoutube?: string;
  observacao?: string;
}

// Neumorphic container reutilizável
const NeumorphicContainer = ({ children, style }: any) => (
  <LinearGradient
    colors={['#FFB84D', '#43E97B', '#46D7FF']}
    start={{ x: 0, y: 0 }}
    end={{ x: 1, y: 1 }}
    style={[styles.neumorphicOuter, style]}
  >
    <LinearGradient
      colors={['#242B55', '#171B36']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.neumorphicInner}
    >
      <View style={styles.cardGlow} />
      {children}
    </LinearGradient>
  </LinearGradient>
);

function getHojeDate() {
  const hoje = new Date();
  hoje.setHours(0, 0, 0, 0);
  return hoje;
}

function dateParaData(dataSelecionada: Date) {
  const dia = String(dataSelecionada.getDate()).padStart(2, '0');
  const mes = String(dataSelecionada.getMonth() + 1).padStart(2, '0');
  const ano = dataSelecionada.getFullYear();
  return `${dia}/${mes}/${ano}`;
}

function dataParaDate(dataTexto?: string) {
  if (!dataTexto || dataTexto.length < 10) return getHojeDate();
  const [dia, mes, ano] = dataTexto.split(/[/-]/).map(Number);
  if (!dia || !mes || !ano) return getHojeDate();
  return new Date(ano, mes - 1, dia);
}

const MESES = [
  'Janeiro', 'Fevereiro', 'Marco', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro',
];

const DIAS_SEMANA = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];

function montarDiasCalendario(mesVisivel: Date) {
  const ano = mesVisivel.getFullYear();
  const mes = mesVisivel.getMonth();
  const primeiroDia = new Date(ano, mes, 1).getDay();
  const totalDias = new Date(ano, mes + 1, 0).getDate();
  const dias: Array<Date | null> = Array(primeiroDia).fill(null);

  for (let dia = 1; dia <= totalDias; dia += 1) {
    dias.push(new Date(ano, mes, dia));
  }

  while (dias.length % 7 !== 0) dias.push(null);
  return dias;
}

export default function AdicionarRepertorio(): JSX.Element {
  const navigation = useNavigation();
  const [titulo, setTitulo] = useState('');
  const [data, setData] = useState('');
  const [responsavel, setResponsavel] = useState('');
  const [musicas, setMusicas] = useState<Musica[]>([]);
  const [musicaNome, setMusicaNome] = useState('');
  const [musicaTom, setMusicaTom] = useState('C');
  const [musicaLinkLetra, setMusicaLinkLetra] = useState('');
  const [musicaLinkYoutube, setMusicaLinkYoutube] = useState('');
  const [musicaObservacao, setMusicaObservacao] = useState('');
  const [loading, setLoading] = useState(false);
  const [calendarioAberto, setCalendarioAberto] = useState(false);
  const [mesCalendario, setMesCalendario] = useState(() => {
    const hoje = getHojeDate();
    return new Date(hoje.getFullYear(), hoje.getMonth(), 1);
  });

  // Animação de alto relevo para o botão
  const saveAnim = React.useRef(new Animated.Value(1)).current;

  const abrirCalendario = () => {
    const dataBase = dataParaDate(data);
    setMesCalendario(new Date(dataBase.getFullYear(), dataBase.getMonth(), 1));
    setCalendarioAberto(true);
  };

  const fecharCalendario = () => setCalendarioAberto(false);

  const mudarMesCalendario = (direcao: -1 | 1) => {
    setMesCalendario(prev => new Date(prev.getFullYear(), prev.getMonth() + direcao, 1));
  };

  const selecionarDataCalendario = (dataSelecionada: Date) => {
    setData(dateParaData(dataSelecionada));
    fecharCalendario();
  };

  const handleAdicionarMusica = () => {
    if (!musicaNome.trim()) {
      Alert.alert('Atenção', 'Informe o nome da música.');
      return;
    }
    setMusicas(prev => [
      ...prev,
      {
        nome: musicaNome,
        tom: musicaTom,
        linkLetra: musicaLinkLetra,
        linkYoutube: musicaLinkYoutube,
        observacao: musicaObservacao,
      }
    ]);
    setMusicaNome('');
    setMusicaTom('C');
    setMusicaLinkLetra('');
    setMusicaLinkYoutube('');
    setMusicaObservacao('');
  };

  const salvarRepertorio = async () => {
    if (!titulo.trim() || !data.trim() || !responsavel.trim() || musicas.length === 0) {
      Alert.alert('Atenção', 'Preencha todos os campos e adicione pelo menos uma música.');
      return;
    }
    setLoading(true);
    try {
      await addDoc(
        collection(db, 'repertorios'),
        {
          titulo,
          data,
          responsavel,
          musicas: musicas.map(m => ({
            nome: m.nome,
            tom: m.tom,
            linkLetra: m.linkLetra,
            linkYoutube: m.linkYoutube,
            observacao: m.observacao,
          })),
          criadoEm: new Date(),
        }
      );
      Alert.alert('Sucesso', 'Repertório criado com sucesso!');
        // incrementa contador remoto (meta/repertorios) e sinal local
        const metaRef = doc(db, 'meta', 'repertorios');
        try {
          await updateDoc(metaRef, { newCount: increment(1), lastUpdated: new Date() });
          console.log('meta/repertorios incremented (create)');
        } catch (e) {
          try {
            await setDoc(metaRef, { newCount: 1, lastUpdated: new Date() }, { merge: true });
            console.log('meta/repertorios created with newCount=1 (create)');
          } catch (err) {
            console.log('Erro ao atualizar contador remoto de repertorios', err);
          }
        }
        try {
          const cur = await AsyncStorage.getItem('nova_repertorio');
          const num = cur ? parseInt(cur, 10) || 0 : 0;
          const novo = num + 1;
          await AsyncStorage.setItem('nova_repertorio', String(novo));
          await Notifications.setBadgeCountAsync(novo);
        } catch (e) {
          console.log('Não foi possível setar badge/flag local de repertorio', e);
        }
      navigation.goBack();
    } catch (error) {
      Alert.alert('Erro', 'Não foi possível salvar o repertório.');
    } finally {
      setLoading(false);
    }
  };

  // Efeito de alto relevo no botão
  const handlePressIn = () => {
    Animated.spring(saveAnim, {
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  };
  const handlePressOut = () => {
    Animated.spring(saveAnim, {
      toValue: 1,
      friction: 3,
      tension: 40,
      useNativeDriver: true,
    }).start();
  };

  return (
    <LinearGradient colors={['#0B1630', '#151936', '#241A3D']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.bg}>
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <ScrollView contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
          <View style={styles.topBar}>
            <TouchableOpacity style={[styles.topButton, styles.topButtonLeft]} onPress={() => navigation.navigate('Inicio')} activeOpacity={0.85}>
              <MaterialCommunityIcons name="home-variant-outline" size={24} color="#43E97B" />
            </TouchableOpacity>
            <View style={styles.topTitleContainer}>
              <View style={styles.titleIconWrap}>
                <MaterialCommunityIcons name="playlist-plus" size={23} color="#111827" />
              </View>
              <Text style={styles.topTitle}>Adicionar Repertorio</Text>
            </View>
            <TouchableOpacity style={[styles.topButton, styles.topButtonRight]} onPress={() => navigation.goBack()} activeOpacity={0.85}>
              <MaterialIcons name="keyboard-backspace" size={25} color="#46D7FF" />
            </TouchableOpacity>
          </View>
          <View style={styles.card}>
            <NeumorphicContainer style={styles.inputGroup}>
              <View style={styles.labelRow}>
                <View style={styles.fieldIconWrap}>
                  <MaterialCommunityIcons name="format-title" size={18} color="#111827" />
                </View>
                <Text style={styles.label}>Titulo</Text>
              </View>
              <TextInput
                style={styles.input}
                value={titulo}
                onChangeText={setTitulo}
                placeholder="Titulo"
                placeholderTextColor="#90caf9"
              />
            </NeumorphicContainer>
            <NeumorphicContainer style={styles.inputGroup}>
              <View style={styles.labelRow}>
                <View style={styles.fieldIconWrap}>
                  <MaterialCommunityIcons name="calendar-month" size={18} color="#111827" />
                </View>
                <Text style={styles.label}>Data</Text>
              </View>
              <TouchableOpacity style={styles.dateInputButton} onPress={abrirCalendario} activeOpacity={0.85}>
                <Text style={[styles.dateInputText, !data && styles.dateInputPlaceholder]}>
                  {data || 'Selecionar data'}
                </Text>
              </TouchableOpacity>
            </NeumorphicContainer>
            <NeumorphicContainer style={styles.inputGroup}>
              <View style={styles.labelRow}>
                <View style={styles.fieldIconWrap}>
                  <MaterialCommunityIcons name="account-tie" size={18} color="#111827" />
                </View>
                <Text style={styles.label}>Responsavel</Text>
              </View>
              <TextInput
                style={styles.input}
                value={responsavel}
                onChangeText={setResponsavel}
                placeholder="Responsavel"
                placeholderTextColor="#90caf9"
              />
            </NeumorphicContainer>

            <NeumorphicContainer style={styles.section}>
              <View style={styles.labelRow}>
                <View style={styles.fieldIconWrap}>
                  <MaterialCommunityIcons name="music-circle" size={18} color="#111827" />
                </View>
                <Text style={styles.sectionTitle}>Adicionar Musica</Text>
              </View>              <View style={styles.musicRow}>
                <TextInput
                  style={[styles.input, { flex: 2, marginRight: 8 }]}
                  placeholder="Nome da música"
                  placeholderTextColor="#90caf9"
                  value={musicaNome}
                  onChangeText={setMusicaNome}
                />
              </View>
              <View style={styles.musicRow}>
                <TextInput
                  style={[styles.input, { flex: 2, marginRight: 8 }]}
                  placeholder="Link da letra (opcional)"
                  placeholderTextColor="#90caf9"
                  value={musicaLinkLetra}
                  onChangeText={setMusicaLinkLetra}
                  autoCapitalize="none"
                  autoCorrect={false}
                  keyboardType="url"
                />
              </View>
              <View style={styles.musicRow}>
                <TextInput
                  style={[styles.input, { flex: 2, marginRight: 8 }]}
                  placeholder="Link do YouTube (opcional)"
                  placeholderTextColor="#90caf9"
                  value={musicaLinkYoutube}
                  onChangeText={setMusicaLinkYoutube}
                  autoCapitalize="none"
                  autoCorrect={false}
                  keyboardType="url"
                />
              </View>
              <View style={styles.musicRow}>
                <TextInput
                  style={[styles.input, styles.observacaoInput]}
                  placeholder="Observacao (opcional)"
                  placeholderTextColor="#90caf9"
                  value={musicaObservacao}
                  onChangeText={setMusicaObservacao}
                  multiline
                  textAlignVertical="top"
                />
              </View>
              <View style={styles.tonesBlock}>
                <Text style={styles.tonesLabel}>Tons maiores:</Text>
                <FlatList
                  data={tonsMaiores}
                  horizontal
                  showsHorizontalScrollIndicator={false}
                  keyExtractor={item => item}
                  renderItem={({ item }) => (
                    <TouchableOpacity
                      style={[
                        styles.toneButton,
                        musicaTom === item && styles.toneButtonSelected
                      ]}
                      onPress={() => setMusicaTom(item)}
                    >
                      <Text style={[
                        styles.toneButtonText,
                        musicaTom === item && styles.toneButtonTextSelected
                      ]}>{item}</Text>
                    </TouchableOpacity>
                  )}
                />
              </View>
              <View style={styles.tonesBlock}>
                <Text style={styles.tonesLabel}>Tons menores:</Text>
                <FlatList
                  data={tonsMenores}
                  horizontal
                  showsHorizontalScrollIndicator={false}
                  keyExtractor={item => item}
                  renderItem={({ item }) => (
                    <TouchableOpacity
                      style={[
                        styles.toneButton,
                        musicaTom === item && styles.toneButtonSelected
                      ]}
                      onPress={() => setMusicaTom(item)}
                    >
                      <Text style={[
                        styles.toneButtonText,
                        musicaTom === item && styles.toneButtonTextSelected
                      ]}>{item}</Text>
                    </TouchableOpacity>
                  )}
                />
              </View>
              <TouchableOpacity style={styles.addMusicButton} onPress={handleAdicionarMusica}>
                <Text style={styles.addMusicButtonText}>Adicionar Música</Text>
              </TouchableOpacity>
            </NeumorphicContainer>

            <FlatList
              data={musicas}
              keyExtractor={(_, idx) => idx.toString()}
              renderItem={({ item, index }) => (
                <View style={styles.musicListItem}>
                  <View style={styles.musicListInfo}>
                    <Text style={styles.musicListTitle}>{item.nome}</Text>
                    {item.observacao ? (
                      <Text style={styles.musicListObs}>{item.observacao}</Text>
                    ) : null}
                  </View>
                  <Text style={styles.musicListTom}>{item.tom}</Text>
                  <TouchableOpacity
                    style={[styles.fileButton, { marginLeft: 4 }]}
                    onPress={() => {
                      if (item.linkLetra) {
                        Linking.openURL(item.linkLetra);
                      } else {
                        Alert.alert('Sem link', 'Nenhum link foi adicionado para esta música.');
                      }
                    }}
                  >
                    <Text style={styles.fileButtonText}>
                      {item.linkLetra ? 'Ver Letra' : 'Letra'}
                    </Text>
                  </TouchableOpacity>
                  {item.linkYoutube ? (
                    <TouchableOpacity
                      style={[styles.fileButton, { marginLeft: 8, backgroundColor: '#E53935' }]}
                      onPress={() => Linking.openURL(item.linkYoutube!)}
                    >
                      <Text style={styles.fileButtonText}>YouTube</Text>
                    </TouchableOpacity>
                  ) : null}
                </View>
              )}
              ListHeaderComponent={
                musicas.length > 0 ? (
                  <View style={styles.musicListHeader}>
                    <Text style={{ flex: 2, fontWeight: 'bold', color: '#1565c0' }}>Música</Text>
                    <Text style={{ flex: 1, fontWeight: 'bold', color: '#1565c0' }}>Tom</Text>
                    <Text style={{ flex: 2, fontWeight: 'bold', color: '#1565c0' }}>Letra</Text>
                    <Text style={{ flex: 1, fontWeight: 'bold', color: '#1565c0' }}>YouTube</Text>
                  </View>
                ) : null
              }
            />

            <Animated.View style={{ transform: [{ scale: saveAnim }] }}>
              <TouchableOpacity
                style={styles.saveButton}
                onPress={salvarRepertorio}
                disabled={loading}
                onPressIn={handlePressIn}
                onPressOut={handlePressOut}
                activeOpacity={0.85}
              >
                {loading ? (
                  <ActivityIndicator color="#fff" />
                ) : (
                  <Text style={styles.saveButtonText}>Salvar Repertório</Text>
                )}
              </TouchableOpacity>
            </Animated.View>
            <TouchableOpacity style={styles.cancelButton} onPress={() => navigation.goBack()}>
              <Text style={styles.cancelButtonText}>Cancelar</Text>
            </TouchableOpacity>
          </View>
        </ScrollView>
        <Modal
          transparent
          visible={calendarioAberto}
          animationType="fade"
          onRequestClose={fecharCalendario}
        >
          <View style={styles.calendarioOverlay}>
            <LinearGradient
              colors={['#252B55', '#171B38']}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.calendarioModal}
            >
              <View style={styles.calendarioHeader}>
                <TouchableOpacity style={styles.calendarioNavBtn} onPress={() => mudarMesCalendario(-1)}>
                  <Text style={styles.calendarioNavText}>{'<'}</Text>
                </TouchableOpacity>
                <View style={styles.calendarioTituloBox}>
                  <Text style={styles.calendarioTitulo}>{MESES[mesCalendario.getMonth()]}</Text>
                  <Text style={styles.calendarioAno}>{mesCalendario.getFullYear()}</Text>
                </View>
                <TouchableOpacity style={styles.calendarioNavBtn} onPress={() => mudarMesCalendario(1)}>
                  <Text style={styles.calendarioNavText}>{'>'}</Text>
                </TouchableOpacity>
              </View>

              <View style={styles.calendarioSemana}>
                {DIAS_SEMANA.map((dia, idx) => (
                  <Text key={`${dia}-${idx}`} style={styles.calendarioSemanaTexto}>{dia}</Text>
                ))}
              </View>

              <View style={styles.calendarioGrid}>
                {montarDiasCalendario(mesCalendario).map((dia, idx) => {
                  const dataFormatada = dia ? dateParaData(dia) : '';
                  const selecionada = !!dia && dataFormatada === data;
                  const hoje = !!dia && dataFormatada === dateParaData(getHojeDate());
                  return (
                    <TouchableOpacity
                      key={`${dataFormatada || 'vazio'}-${idx}`}
                      style={[
                        styles.calendarioDia,
                        !dia && styles.calendarioDiaVazio,
                        hoje && styles.calendarioDiaHoje,
                        selecionada && styles.calendarioDiaSelecionado,
                      ]}
                      disabled={!dia}
                      onPress={() => dia && selecionarDataCalendario(dia)}
                      activeOpacity={0.82}
                    >
                      <Text
                        style={[
                          styles.calendarioDiaTexto,
                          hoje && styles.calendarioDiaTextoHoje,
                          selecionada && styles.calendarioDiaTextoSelecionado,
                        ]}
                      >
                        {dia ? dia.getDate() : ''}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>

              <View style={styles.calendarioAcoes}>
                <TouchableOpacity style={styles.calendarioCancelar} onPress={fecharCalendario}>
                  <Text style={styles.calendarioCancelarTexto}>Cancelar</Text>
                </TouchableOpacity>
                <TouchableOpacity style={styles.calendarioHojeBtn} onPress={() => selecionarDataCalendario(getHojeDate())}>
                  <Text style={styles.calendarioHojeTexto}>Hoje</Text>
                </TouchableOpacity>
              </View>
            </LinearGradient>
          </View>
        </Modal>
      </KeyboardAvoidingView>
    </LinearGradient>
  );
}

